head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > interactionEnterKey]<br/>입력값을 검색키로 사용하여 아이템을 동적으로 요청할 입력키를 설정합니다.",
    "validation" : [
        "interactionMode='true' 인 경우에 동작합니다.",
        "true 설정 시, 입력창에서 Enter 키를 누를 때만 입력값을 검색키로 아이템 데이터를 요청합니다.",
        "true 설정 시, 입력창에 값을 입력하거나 아래 화살표키를 눌러도 아이템 데이터를 요청하지 않습니다.",
        "false 설정 시, 입력창에 값을 입력하거나 아이템 리스트창이 닫힌 상태에서 아래 화살표키를 누를 때 아이템 데이터를 요청합니다.",
        "미설정 시, 입력창에 값을 입력하거나 아이템 리스트창이 닫힌 상태에서 아래 화살표키를 누를 때 아이템 데이터를 요청합니다.",
        "false 설정 시, 편집 모드일때 입력값 검색이 된 후 편집 모드를 해제하지 않고 입력값을 모두 삭제하면 아이템 데이터를 요청합니다.",
        "사용자의 입력값이 직전 검색키와 같으면 Enter 키를 눌러도 아이템 데이터를 요청하지 않습니다."
    ]
}

// submissionFunc 가 검색 결과로 추가할 아이템 (초기 아이템은 두지 않아 입력창이 빈 상태로 시작)
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Seongnam", "value" : "SNM" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Jeju", "value" : "CJU" }
];

// submissionFunc 호출 기록 (요청 확인 버튼 클릭 시 출력 후 비움)
scwin.arrRequest = [];



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 기본값 : interactionMode=true, interactionEnterKey=true
    con_interactionMode.setValue("2");
    con_interactionEnterKey.setValue("2");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') target1.remove();

    $c.gcm.createLabel('label="[전제]\n- 아이템 : Seoul, Seongnam, Busan, Jeju\n- submissionFunc 는 검색어로 시작하는 아이템을 목록에 표시\n- 직전 검색어와 같으면 다시 요청하지 않으므로 절차마다 Target 재생성 후 시작\n- 요청 확인 클릭은 편집 모드를 해제하므로 절차 마지막에만 클릭\n- interactionEnterKey=false 는 입력 후 잠시 뒤 요청하므로 Se 를 천천히 입력하면 S 요청이 추가될 수 있음\n[절차]\n1. 입력창 클릭 -> Se 입력 -> Enter -> Enter -> 요청 확인\n2. Se 입력(interactionEnterKey=true 는 Enter 추가) -> 목록에서 Seoul 클릭 -> 입력창 클릭 -> 아래 화살표키 -> 요청 확인\n3. Se 입력(interactionEnterKey=true 는 Enter 추가) -> 목록이 열린 상태에서 Ctrl+A 후 Backspace 로 모두 삭제 -> 요청 확인\n[확인] 요청 횟수와 검색어(keyCode : 13=Enter, 40=아래 화살표키, 8=Backspace, 그 외=입력 문자)"', '', 'label1');

    scwin.arrRequest = [];

    let properties = {
        interactionMode : con_interactionMode.getText(),
        interactionEnterKey : con_interactionEnterKey.getText(),
        submissionFunc : "scwin.searchItem",
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices></w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// interactionMode=true 일때 아이템 데이터 요청 함수 : 호출 기록 후 검색어로 시작하는 아이템을 목록에 표시
// initAutoComplete() 는 입력창 값까지 비워 입력값 삭제 절차가 성립하지 않으므로 아이템만 제거하는 removeAll() 사용
scwin.searchItem = function (searchStr, keyCode) {
    scwin.arrRequest.push((searchStr === "" ? "(빈 문자열)" : searchStr) + "(" + keyCode + ")");
    target1.removeAll();
    scwin.arrCity.forEach(function (item) {
        if (item.label.indexOf(searchStr) === 0) {
            target1.addItem(item.label, item.value);
        }
    });
    target1.openTable();
};



// 직전 확인 이후의 아이템 데이터 요청 횟수와 검색어 출력 후 기록 비움 (validation 1 ~ 7)
scwin.btn_getRequest_onclick = function (e) {
    let strResult = "요청 횟수 : " + scwin.arrRequest.length;
    if (scwin.arrRequest.length > 0) {
        strResult += " -> 검색어(keyCode) : " + scwin.arrRequest.join(" / ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue(strResult);
    scwin.arrRequest = [];
};
